return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'uz_UZ','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'WordPress fayllaringiz va maʼlumotlar bazangizni oʻzingizning xotirangizga — Dropbox, Google Drive, Cloudflare R2, Amazon S3 yoki har qanday S3 mos keladigan bucketʼga zaxiralaydi — ularni bir urinishda tiklaydi hamda boshqa zaxiralash va koʻchirish plaginlari tomonidan yaratilgan zaxira nusxalarini import qiladi.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Zaxira nusxalar','Get Pro: schedules, several storages, encryption'=>'Pro versiyasini oling: jadvallar, bir nechta xotira joylari, shifrlash','Working…'=>'Bajarilmoqda…','Finished'=>'Tugallandi','Failed'=>'Muvaffaqiyatsiz','Cancelled'=>'Bekor qilindi','Cancel'=>'Bekor qilish','Restore'=>'Qayta tiklash','Delete'=>'Oʻchirish','Delete this backup from your storage? This cannot be undone.'=>'Bu zaxira nusxasi xotirangizdan oʻchirilsinmi? Ushbu amalni bekor qilib boʻlmaydi.','No backups yet. Press “Back up now” to make the first one.'=>'Hozircha zaxira nusxalari yoʻq. Birinchisini yaratish uchun "Hozir zaxiralash" tugmasini bosing.','Reading your storage…'=>'Xotirangiz oʻqilmoqda…','a complete backup, as opposed to an incremental oneFull backup'=>'Toʻliq zaxira nusxasi','a backup holding only what changed since an earlier oneIncremental backup'=>'Ortib boruvchi zaxira nusxa','Encrypted'=>'Shifrlangan','From another site'=>'Boshqa saytdan','Database'=>'Maʼlumotlar bazasi','Files'=>'Fayllar','Uploading %1$s: %2$s%%'=>'%1$s yuklanmoqda: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Ochilgan oynada Dropbox-ga kiring, soʻngra Dropbox sizga koʻrsatgan kodni joylashtiring:','Saved.'=>'Saqlandi.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Ushbu manzil plaginidan olib tashlansinmi? Unda saqlangan zaxira nusxalar oʻchirilmaydi.','Reload the page to see the restored site.'=>'Qayta tiklangan saytni ko‘rish uchun sahifani qayta yuklang.','Storage'=>'Xotira','Import & migrate'=>'Import qilish va koʻchirish','Settings'=>'Sozlamalar','Sections'=>'Boʻlimlar','Google Drive is connected.'=>'Google Drive ulangan.','Google Drive could not be connected.'=>'Google Drive ulanmadi.','Details'=>'Tafsilotlar','Back up now'=>'Hozir zaxiralang','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Zaxira nusxalar ushbu serverga emas, oʻzingizning xotirangizga yuboriladi. Avval <a href="%s">xotirangizni ulang</a>.','What to back up'=>'Nimalarni zaxiralash kerak','Files and database'=>'Fayllar va maʼlumotlar bazasi','Database only'=>'Faqat maʼlumotlar bazasi','Files only'=>'Faqat fayllar','Note (optional)'=>'Eslatma (ixtiyoriy)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Keyingi qism yaratilishidan oldin har bir qism xotirangizga yuklanadi va ushbu serverdan o‘chiriladi, shuning uchun zaxira nusxasi hech qachon xostingingizda joy egallamaydi.','Your backups'=>'Zaxira nusxalaringiz','Refresh'=>'Yangilash','Restore this backup'=>'Ushbu zaxira nusxani tiklash','Passphrase'=>'Parol iborasi','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Tushunaman, bu ushbu sayt fayllari va maʼlumotlar bazasini zaxira nusxadagilar bilan almashtiradi. Zaxira nusxada boʻlmagan fayllar saqlab qolinadi.','Recent activity'=>'So‘nggi faoliyat','Backup'=>'Zaxira nusxa','Restore / import'=>'Tiklash / import qilish','Running'=>'Ishlamoqda','Your storage'=>'Sizning xotirangiz' . "\0" . 'Saqlash manzillaringiz','No storage yet. Choose where your backups go below.'=>'Hozircha xotira yoʻq. Zaxira nusxalaringiz qayerga borishini quyida tanlang.','Ready'=>'Tayyor','Not connected'=>'Ulanmagan','Connect'=>'Ulanish','Test'=>'Sinov','Edit'=>'Tahrirlash','Remove'=>'Olib tashlash','Add storage'=>'Xotira qoʻshish','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Zaxira nusxalari bitta saqlash manziliga yuboriladi. Boshqasidan foydalanish uchun yuqoridagisini tahrirlang yoki olib tashlang.','Kind of storage'=>'Xotira turi','Name (for you)'=>'Nomi (siz uchun)','Provider'=>'Provayder','Cloudflare account id'=>'Cloudflare hisob ID-si','Endpoint address'=>'Yakuniy nuqta manzili','Region'=>'Mintaqa','Bucket'=>'Bucket','Access key id'=>'Kirish kaliti identifikatori','Secret access key'=>'Maxfiy kirish kaliti','Leave empty to keep the saved key'=>'Saqlangan kalitni saqlab qolish uchun boʻsh qoldiring','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Cloudflare R2 uchun: Cloudflare boshqaruv panelida R2 boʻlimini oching, savat (bucket) yarating, soʻngra “Manage R2 API tokens” → ushbu savat uchun Object Read & Write ruxsatiga ega token yarating va bu yerga kirish kaliti identifikatori (access key id) hamda maxfiy kalitni nusxalang.','Dropbox app key'=>'Dropbox ilova kaliti','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'dropbox.com/developers/apps (Scoped access, App folder) sahifasida files.content.read, files.content.write va files.metadata.read ruxsatlariga ega ilova yarating va uning App key kodini bu yerga nusxalang. Saqlang, soʻngra Ulanish tugmasini bosing.','OAuth client id'=>'OAuth mijoz identifikatori','OAuth client secret'=>'OAuth mijoz siri','Leave empty to keep the saved secret'=>'Saqlangan sirni saqlab qolish uchun boʻsh qoldiring','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Google Cloud Console’da Google Drive API’ni yoqing, soʻngra ushbu manzilni ruxsat berilgan qayta yoʻnaltirish URI sifatida koʻrsatib, “Veb-ilova” turidagi OAuth mijozini yarating:','Save, then press Connect. The plugin only sees the files it creates.'=>'Saqlang, soʻngra Ulanish tugmasini bosing. Plagin faqat oʻzi yaratgan fayllarni koʻradi.','Folder inside the storage (optional)'=>'Xotira ichidagi jild (ixtiyoriy)','Save storage'=>'Xotirani tejang','Import a backup from another plugin or host'=>'Boshqa plagin yoki xostdan zaxira nusxasini import qiling','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate yoki oʻzining .sql damplari bilan birga WordPress saytining har qanday zip/tar arxivi orqali yaratilgan zaxira nusxadan saytni kiriting. Tarkib wp-content ichiga joylashadi va maʼlumotlar bazasi ushbu saytnikini almashtiradi; manzillar avtomatik ravishda ushbu saytnikiga oʻzgartiriladi.','Upload from your computer'=>'Kompyuteringizdan yuklang','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Zaxiraning barcha fayllarini birdaniga tanlang (UpdraftPlus bir nechtasini yaratadi). Katta fayllar kichik qismlarda yuboriladi, shuning uchun xostingizning yuklash cheklovi qoʻllanilmaydi.','Or from links (Google Drive, Dropbox or any download address)'=>'Yoki havolalardan (Google Drive, Dropbox yoki har qanday yuklab olish manzili)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Har bir qatorda bitta havola. Google Drive va Dropbox uchun faylni "havolaga ega boʻlgan har qanday odam" bilan ulashing va ushbu havolani joylashtiring; keyin ulashishni yana oʻchirib qoʻying.','Or a file already on this server'=>'Yoki ushbu serverda allaqachon mavjud bo‘lgan fayl','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Arxivlarni FTP yoki hostingizning fayl menejeri orqali %s ga yuklang va ushbu sahifani qayta yuklang.','Or a deploy code from another site'=>'Yoki boshqa saytdan joylashtirish kodi','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Agar boshqa sayt sizga Zinn® Backups joylashtirish kodini bergan boʻlsa, uning xotira kalitlarini ulashmagan holda ushbu zaxira nusxasini bu saytga koʻchirish uchun uni bu yerga joylashtiring. Kod bir necha soat davomida ishlaydi; unga parol kabi munosabatda boʻling.','Passphrase (only if that backup is encrypted)'=>'Parol iborasi (faqat oʻsha zaxira nusxa shifrlangan boʻlsa)','Import'=>'Import qilish','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Import ushbu sayt tarkibi va maʼlumotlar bazasini almashtirishini tushunaman. Shundan soʻng, import qilingan saytdagi hisob bilan kiring.','Moving to Zinn® hosting?'=>'Zinn® hostingiga oʻtyapsizmi?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® saytingizni eski hostingingizdan koʻchirib berishi mumkin. Agar eski hostingingiz sizga FTP, SSH yoki boshqaruv paneliga kirish huquqini bermasa, eski saytga Zinn® Migrate dasturini oʻrnating; u bu yerga import qilishingiz yoki Zinn® xizmatiga topshirishingiz mumkin boʻlgan bitta arxiv yaratadi.','What goes into a backup'=>'Zaxira nusxasiga nimalar kiradi','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'WordPress’ning o‘z fayllarini (wp-admin, wp-includes) kiriting. Odatda kerak emas: WordPress’ni har doim qayta o‘rnatish mumkin.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Shuningdek, ushbu jildlar yoki fayllarni chiqarib tashlang (har bir qatorda bittadan, WordPress jildiga nisbatan)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Har doim chiqarib tashlanadi: keshlar, yangilashning vaqtinchalik joyi va boshqa zaxira nusxa plaginlarining oʻz arxiv jildlari:','Size of each part (MB)'=>'Har bir qismning hajmi (MB)','Save settings'=>'Sozlamalarni saqlash','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Zaxira nusxasining bir qismini yozish uchun ochib bo‘lmadi. wp-content jildida bo‘sh joy borligini tekshiring.','A backup part could not be written. Check that wp-content has free space.'=>'Zaxira nusxasining bir qismini yozib boʻlmadi. wp-content papkasida boʻsh joy borligini tekshiring.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Avval Storage yorligʻida saqlash joyini ulang: zaxira nusxalari ushbu serverda emas, oʻzingizning xotirangizda saqlanadi.','Multisite networks are not supported yet.'=>'Koʻpsaytli tarmoqlar hali qoʻllab-quvvatlanmaydi.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'Ushbu serverning PHP versiyasida ZipArchive kengaytmasi yoʻq. Uni faollashtirishni hosting provayderingizdan soʻrang.','Starting'=>'Boshlanmoqda','Listing files'=>'Fayllar ro‘yxati keltirilmoqda','Backing up the database'=>'Maʼlumotlar bazasining zaxira nusxasi yaratilmoqda','Packing files'=>'Fayllar paketlanmoqda','Uploading to your storage'=>'Xotirangizga yuklanmoqda','Finishing'=>'Tugallanmoqda','The backup reached an unknown stage.'=>'Zaxira nusxasi nomaʼlum bosqichga yetdi.','Backup %s started.'=>'%s zaxira nusxalanishi boshlandi.','Found %1$s files (%2$s).'=>'%1$s ta fayl topildi (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Maʼlumotlar bazasi: %1$d ta jadval, %2$s ta qator, %3$s siqilgan.','Backup complete: %1$s stored in %2$d destination.'=>'Zaxira nusxalash yakunlandi: %1$s %2$d manzilda saqlandi.' . "\0" . 'Zaxira nusxalash yakunlandi: %1$s %2$d ta manzilda saqlandi.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Allaqachon yuklangan baʼzi qismlarni xotirangizdan olib tashlab boʻlmadi; ular toʻliq boʻlmagan zaxira nusxa jildida joylashgan va qayta tiklash uchun hech qachon taklif qilinmaydi.','A storage destination was removed while the backup was running.'=>'Zaxira nusxalash jarayoni davom etayotganda saqlash manzili olib tashlandi.','That is not a backup folder.'=>'Bu zaxira nusxa jildi emas.','That storage destination is no longer saved on this site.'=>'Ushbu xotira manzili endi bu saytda saqlanmaydi.','Later incremental backups are built on this one. Delete those first.'=>'Keyingi bosqichli zaxira nusxalari shunga asoslangan. Avval ularni oʻchirib tashlang.','This file is not an encrypted Zinn® Backups file.'=>'Bu fayl shifrlangan Zinn® Backups fayli emas.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Zaxira nusxasini shifrdan chiqarib boʻlmadi: maxfiy ibora notoʻgʻri yoki fayl shikastlangan.','The encrypted backup file is incomplete.'=>'Shifrlangan zaxira fayli toʻliq emas.','The database file could not be written. Check that wp-content has free space.'=>'Maʼlumotlar bazasi faylini yozib boʻlmadi. wp-content ichida boʻsh joy borligini tekshiring.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Bu joylashtirish kodi emas. Joylashtirish kodi zbdeploy1 bilan boshlanadi.','That deploy code is damaged. Copy it again from the other site.'=>'Ushbu joylashtirish kodi shikastlangan. Uni boshqa saytdan qayta nusxalang.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Joylashtirish kodining amal qilish muddati tugagan yoki uning zaxira nusxasi oʻchirib tashlangan. Boshqa saytda yangi kod yarating.','That deploy code does not point at a Zinn® Backups backup.'=>'Ushbu joylashtirish kodi Zinn® Backups zaxira nusxasiga ishora qilmaydi.','The deploy code has expired. Make a new code on the other site.'=>'Oʻrnatish kodining amal qilish muddati tugadi. Boshqa saytda yangi kod yarating.','The server stopped honouring partial downloads. Start the import again.'=>'Server qisman yuklab olishlarni qabul qilishni toʻxtatdi. Importni qaytadan boshlang.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Havola fayl oʻrniga veb-sahifani ochdi. Google Drive va Dropbox uchun faylni "havolaga ega har qanday foydalanuvchi" bilan ulashing va ushbu havolani joylashtiring.','The link answered with HTTP %d.'=>'Havola HTTP %d bilan javob berdi.','The file list could not be written.'=>'Fayllar roʻyxatini yozib boʻlmadi.','The storage service could not be reached: %s'=>'Xotira xizmati bilan bogʻlanib boʻlmadi: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s quyidagi HTTP %2$d bilan javob berdi: %3$s','no details given'=>'Tafsilotlar kiritilmagan','You are not allowed to manage backups.'=>'Sizda zaxira nusxalarini boshqarish huquqi yoʻq.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Tiklash jarayoni ushbu sayt fayllari va maʼlumotlar bazasini almashtirishini tasdiqlash uchun katakchani belgilang.','Save the destination first.'=>'Avval manzilni saqlang.','Connected: a test file was written and removed.'=>'Ulandi: sinov fayli yozildi va oʻchirildi.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Avval Dropbox ilovangizning ilova kalitini kiriting (shakl yonidagi bosqichlarga qarang).','This kind of storage does not sign in.'=>'Ushbu turdagi xotira tizimga kirmaydi.','The sign-in expired. Press Connect again.'=>'Kirish muddati tugadi. Yana Ulanish tugmasini bosing.','Dropbox is connected.'=>'Dropbox ulandi.','Settings saved.'=>'Sozlamalar saqlandi.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Boshqa zaxira nusxalash, tiklash yoki import jarayoni davom etmoqda. U tugashini kuting yoki uni bekor qiling.','The upload was not started properly. Start again.'=>'Yuklash toʻgʻri boshlanmadi. Qaytadan boshlang.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Qism yetib kelmadi. Serveringiz yuklash hajmini cheklashi mumkin; qayta urinib koʻring.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Import ushbu sayt tarkibini va maʼlumotlar bazasini almashtirishini tasdiqlash uchun katakchani belgilang.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Import qilish uchun arxivni tanlang: uni yuklang, havolani qoʻying yoki import jildidan birini tanlang.','Hosting customer? Get %1$d%% off %2$s'=>'Xosting mijozi? %2$s uchun %1$d%% chegirma oling','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Zinn Digital® hosting mijozi sifatida siz birinchi toʻlovingiz uchun %d%% chegirma beruvchi shaxsiy kodga ega boʻlasiz. Yangilanishlar odatiy narxda amalga oshiriladi.','Get my %d%% code and go to checkout'=>'Mening %d%% kodimni oling va buyurtmani rasmiylashtirishga oʻting','Sorry, you are not allowed to do that.'=>'Kechirasiz, buni amalga oshirishga ruxsatingiz yoʻq.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Ushbu chegirma faol va toʻlangan hosting rejasiga ega mijozlar uchun amal qiladi. Bepul sinov muddatlari mos kelmaydi.','You have already used your hosting-customer discount for this plugin.'=>'Siz ushbu plagin uchun hosting mijozi chegirmasidan allaqachon foydalangansiz.','We could not get your code just now. Please try again in a few minutes.'=>'Hozirgina kodingizni ololmadik. Iltimos, bir necha daqiqadan so‘ng qayta urinib ko‘ring.','Reading the backup'=>'Zaxira nusxa oʻqilmoqda','Downloading the archive'=>'Arxiv yuklab olinmoqda','Recognising the archive'=>'Arxiv aniqlanmoqda','Restoring files'=>'Fayllar tiklanmoqda','Downloading the database'=>'Maʼlumotlar bazasi yuklab olinmoqda','Restoring the database'=>'Maʼlumotlar bazasi tiklanmoqda','Updating the site address'=>'Sayt manzili yangilanmoqda','Switching to the restored database'=>'Qayta tiklangan maʼlumotlar bazasiga oʻtilmoqda','The restore reached an unknown stage.'=>'Qayta tiklash nomaʼlum bosqichga yetdi.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Ushbu jildda toʻliq Zinn® Backups zaxira nusxasi mavjud emas (manifest yetishmayapti).','This backup is encrypted. Enter its passphrase to restore it.'=>'Ushbu zaxira nusxa shifrlangan. Uni tiklash uchun parolli iborasini kiriting.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Ushbu oʻsib boruvchi zaxira nusxasi uchun xotirada mavjud boʻlmagan %s zaxira nusxasi talab qilinadi.','Restoring the backup of %1$s (%2$d file parts).'=>'%1$s zaxira nusxasi tiklanmoqda (%2$d fayl qismlari).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'%1$s fayli ustidan yozib boʻlmadi, chunki bu saytga uni oʻzgartirishga ruxsat berilmagan va u oʻz holicha qoldirildi: %2$s' . "\0" . 'Ushbu saytga ularni oʻzgartirishga ruxsat berilmaganligi sababli %1$s ta fayl ustiga yozilmadi va ular oʻz holicha qoldirildi: %2$s','Restored %s files.'=>'%s ta fayl tiklandi.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s yuklab olingandan keyin oʻzining nazorat summasiga mos kelmadi. Xotiradagi nusxa shikastlangan boʻlishi mumkin.','%s did not arrive. Upload it again.'=>'%s yetib kelmadi. Iltimos, uni qayta yuklang.','Recognised: %s.'=>'Taniqli: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'wp-content ichiga %1$s ta fayl import qilindi (%2$s tasi qoldirildi: keshlar, drop-inlar va boshqa zaxira plaginlarining jildlari).','The archive has no database dump, so only files were imported.'=>'Arxivda ma\'lumotlar bazasi nusxasi yo\'q, shuning uchun faqat fayllar import qilindi.','Database restored into %d temporary tables.'=>'Maʼlumotlar bazasi %d ta vaqtinchalik jadvalga qayta tiklandi.','%s has no WordPress tables in it and was skipped.'=>'%s ichida hech qanday WordPress jadvallari yoʻq va u oʻtkazib yuborildi.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Zaxira nusxaning maʼlumotlar bazasida hech qanday WordPress jadvallari yoʻq, shuning uchun hech narsa almashtirilmadi.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Ushbu zaxira nusxa koʻpsaytli tarmoqqa tegishli. Tarmoqni bitta saytga tiklash qoʻllab-quvvatlanmaydi.','Moving the content from %1$s to %2$s.'=>'Kontent %1$sdan %2$sga koʻchirilmoqda.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Qayta tiklash yakunlandi. Tizimdan chiqqan bo‘lsangiz, qayta tiklangan saytdagi hisob bilan kiring.','Restore complete.'=>'Tiklash yakunlandi.','%1$s — trying again in %2$d seconds.'=>'%1$s — %2$d soniyadan soʻng qayta urinilmoqda.','Cancelled.'=>'Bekor qilindi.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Zaxira nusxalari bitta saqlash manziliga yuboriladi. Boshqasidan foydalanish uchun mavjudini tahrirlang yoki olib tashlang.','The database file could not be opened.'=>'Maʼlumotlar bazasi faylini ochib boʻlmadi.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Ma\'lumotlar bazasi zaxira nusxadagi buyruqni rad etdi: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Qayta tiklangan jadvallarni almashtirib bo‘lmadi: %s. Saytingiz o‘zgarishsiz qoldi.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Vaqtinchalik zaxira nusxa fayllari uchun yozish mumkin boʻlgan jild mavjud emas. wp-content jildini yozish mumkin boʻlgan qiling va qayta urinib koʻring.','Could not create a folder for this job.'=>'Ushbu vazifa uchun jild yaratib boʻlmadi.','%s — guides and services'=>'%s — qoʻllanmalar va xizmatlar','User guides'=>'Foydalanuvchi qoʻllanmalari','Read the %s user guide'=>'%s foydalanuvchi qoʻllanmasini oʻqing','Hide this'=>'Buni yashirish','Zinn® hosting for WordPress'=>'WordPress uchun Zinn® xostingi','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, kundalik zaxira nusxalari, bepul koʻchirish va birdan ortiq saytni boshqaradigan odamlar uchun yaratilgan boshqaruv paneli.','The Zinn® marketplace'=>'Zinn® bozori','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Har ikki tomon rozi boʻlguniga qadar mablagʻ xavfsiz saqlangan holda shakllangan saytlar, domenlar va havolalar joylashtirishni sotib oling va soting.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — bu ish bilan professional tarzda shugʻullanadigan insonlarni yollang','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Bizning global frilans bozorimiz: yozuvchilar, dizaynerlar, dasturchilar va SEO mutaxassislarining 10 000 dan ortiq tayyor xizmatlarini koʻrib chiqing yoki loyiha joylashtiring va ularga taklif kiritish imkonini bering.','See the Zinn Digital® release notes.'=>'Zinn Digital® reliz qaydlarini koʻring.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® yangilash xizmati ushbu yangilanish uchun yuklab olish havolasini taqdim etmadi. Ushbu sayt Zinn® platformasiga ulana olishini tekshiring, soʻng qayta urinib koʻring.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Yangilanishni Zinn® yangilash xizmatidan (%s) yuklab boʻlmadi. Bir necha daqiqadan soʻng qayta urinib koʻring.','The downloaded update failed its integrity check and was not installed.'=>'Yuklab olingan yangilanish butunlik tekshiruvidan o‘tmadi va o‘rnatilmadi.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Zip arxivini ochib bo‘lmadi. U shikastlangan yoki to‘liq bo‘lmasligi mumkin.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Ushbu .wpress fayli biz o‘qiy olmaydigan formatdan foydalanmoqda (u All-in-One WP Migration tomonidan siqilgan yoki shifrlangan bo‘lishi mumkin). Iltimos, uni shifrlashsiz qayta eksport qiling.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Bu Duplicator “DupArchive” (.daf) faylidir. Duplicator ichida arxiv formatini ZIP qilib sozlagan holda paketni qayta yarating, soʻngra uni import qiling.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Ushbu UpdraftPlus maʼlumotlar bazasi zaxira nusxasi shifrlangan. Uni UpdraftPlus orqali shifrdan chiqaring (yoki maʼlumotlar bazasini shifrlashni oʻchirib, qayta zaxira nusxasini oling), soʻngra import qiling.','Database dump'=>'Maʼlumotlar bazasi dampi','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s biz oʻqiy oladigan zaxira nusxa arxivi emas (zip, tar, tar.gz, .wpress, .sql yoki .sql.gz).','Website archive'=>'Veb-sayt arxivi','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s ichida hech qanday WordPress tarkibi (wp-content jildi va maʼlumotlar bazasi nusxasi yoʻq) mavjud emas.','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Ushbu .wpress fayli All-in-One WP Migration tomonidan shifrlangan yoki siqilgan. Uni shifrlash va siqishni oʻchirib qayta eksport qiling, soʻngra oʻshani import qiling.','Other S3-compatible storage'=>'Boshqa S3-mos xotira','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 yoki S3 bilan mos','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Ushbu saytda xotira kalitlarini oʻqib boʻlmadi. Xotira yorligʻida maxfiy kalitni qayta kiriting.','This kind of storage is not known.'=>'Bunday turdagi xotira maʼlum emas.','Choose a kind of storage.'=>'Xotira turini tanlang.','Enter the bucket name and the access key.'=>'Bucket nomini va kirish kalitini kiriting.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Cloudflare hisobingiz identifikatorini (yoki toʻliq R2 oxirgi nuqtasini) kiriting.','Enter the endpoint address of your storage.'=>'Xotirangizning yakuniy nuqta manzilini kiriting.','Enter the OAuth client id from your Google Cloud project.'=>'Google Cloud loyihangizdan OAuth client id kiriting.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox yangilash tokenini qaytarmadi. Ulanishni qaytadan boshlang.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox ulanmagan. Uni Saqlash vositasi varagʻida qayta ulang.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google yangilash tokenini qaytarmadi. Ushbu saytni Google hisobingizning uchinchi tomon kirishidan olib tashlang va qayta ulaning.','That file is not in Google Drive any more.'=>'Ushbu fayl endi Google Drive ichida yoʻq.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive ulanmagan. Uni Xotira varagʻida qayta ulang.','The storage service did not start the upload.'=>'Xotira xizmati yuklashni boshlamadi.','The storage service sent a reply that could not be read.'=>'Xotira xizmati o‘qib bo‘lmaydigan javob yubordi.','A temporary backup file could not be read.'=>'Vaqtinchalik zaxira nusxa faylini oʻqib boʻlmadi.','A deploy link is read-only.'=>'Joylashtirish havolasi faqat oʻqish uchun.','The deploy code has no link for a file this backup needs.'=>'Joylashtirish kodida ushbu zaxira nusxa uchun zarur boʻlgan fayl havolasi yoʻq.','The deploy link'=>'Joylashtirish havolasi']];